-- v0.48: Series Gamma, 10 GPUs (kura's own 88x31 pixel art, first drawn for Rob's Game), all rares of a new type, hardware.
-- A limited series: a print run of 100 copies for all ten together. Rares have no copy cap of their own (v0.31). Additive only,
-- re-runnable (INSERT OR IGNORE, by series name). Push first (so the GIFs are live), then:
--   npx wrangler d1 execute 88x31-db --remote --file=migrations/035_series_gamma.sql
INSERT OR IGNORE INTO series (name, status, sort, released_at, created_at, print_run)
  VALUES ('Gamma', 'active', 3, strftime('%s','now'), strftime('%s','now'), 100);
